SOURCE_ID={key:f'S{201+i}' for i,key in enumerate(URL)}
def refs(*keys):
    return '<p class="src">Sources, passages consultés le 2 novembre 2026 : '+' ; '.join(f'<a href="{URL[k]}" target="_blank" rel="noopener">[{SOURCE_ID.get(k,k)}] {LABEL[k]}</a>' for k in keys)+'.</p>'
def lab(title,text): return f'<div class="lab">{title}</div>{text}'
def table(headers,rows): return '<table class="t"><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
POP={}
def add(key,title,body,*sources): POP[key]=(title,body+refs(*sources))

add('c86-famille','C86 : sept sous-codes, plusieurs lignées et plusieurs parcours',
lab('Définition', '<p>C86 est une rubrique de codage des « autres lymphomes à cellules T/NK spécifiés ». Ses sept sous-codes ne correspondent pas exactement à sept maladies : C86.6 inclut notamment la papulose lymphomatoïde et le lymphome anaplasique cutané primitif. C86.4 conserve un ancien intitulé NK mais inclut la néoplasie blastique à cellules dendritiques plasmacytoïdes (BPDCN), de lignée dendritique. Ce regroupement administratif ne détermine ni un traitement commun ni une biologie uniforme.</p>')+
lab('Évolution et intention', '<p>ENKTL, HSTL, EATL et lymphomes TFH nodaux nécessitent habituellement une prise en charge spécialisée rapide, souvent à intention curative. Le BPDCN suit son propre parcours. À l’autre extrême, chaque lésion de papulose lymphomatoïde peut régresser spontanément ; une surveillance ou un traitement destiné à contrôler les lésions est alors adapté. Un SPTCL sans syndrome d’activation lymphohistiocytaire peut relever d’une immunosuppression plutôt que d’une polychimiothérapie.</p>')+
lab('Trois frontières à mémoriser','<p>Le lymphome anaplasique systémique ALK positif ou négatif appartient à C84.6/C84.7. Le lymphome T gamma-delta cutané n’est pas le SPTCL alpha-bêta de C86.3. La leucémie NK agressive constitue une entité distincte de l’ENKTL, même si certaines revues cliniques les discutent ensemble. Le pathologiste établit l’entité ; le code ne remplace pas cette expertise.</p>')+
lab('Chiffres et limites','<p>La survie spécifique à cinq ans de 99 % pour la papulose lymphomatoïde et celle de 16 % pour l’ENKTL des registres cutanés néerlandais/autrichien ne forment pas un pronostic universel applicable à tout C86. L’âge, le site, le stade, les traitements et le type de mesure diffèrent. Aucun chiffre suisse contemporain par sous-code n’est affirmé ici.</p>'),'CIM','OMS-DC','ESMO25','WHO-CUT','CUT18')

add('c86-classif','Codage historique et classification biologique actuelle',
lab('Deux niveaux','<p>La table CIM-10-GM 2024 est le référentiel de correspondance documenté dans ce dossier ; elle n’est pas présentée comme une certification de toute règle suisse de facturation en 2026. L’OMS 2022 décrit les lignées et entités actuelles. Onkopedia confronte aussi l’ICC 2022 ; l’article ICC original n’a pas été relu intégralement ici.</p>')+
table(['Sous-code','Correspondance et frontière'],[
['C86.0','ENKTL. L’OMS 2022 supprime « type nasal » du nom biologique, car des sites extranodaux autres que le nez existent.'],
['C86.1','HSTL, de phénotype TCR gamma-delta ou alpha-bêta ; une minorité peut être silencieuse pour le TCR. Ne pas additionner des pourcentages approximatifs issus de séries différentes.'],
['C86.2','EATL associé à une entéropathie. MEITL est une entité biologique séparée ; ne pas le renommer « EATL type II » dans la nomenclature actuelle.'],
['C86.3','SPTCL, de lignée T alpha-bêta. Le lymphome T gamma-delta cutané constitue un autre diagnostic.'],
['C86.4','Ancien intitulé « lymphome blastique NK », incluant BPDCN. L’OMS 2022 le place parmi les néoplasies dendritiques/histiocytaires.'],
['C86.5','Lymphome TFH nodal de type angio-immunoblastique (nTFHL-AI), ancien AITL. Les types folliculaire et sans autre spécification sont distincts.'],
['C86.6','Proliférations cutanées primitives CD30 positives : LyP et pcALCL notamment. Le bilan initial distingue atteinte primitive cutanée et localisation secondaire d’un lymphome systémique.']])+
lab('Piège de mise à jour','<p>Une publication récente peut conserver un vocabulaire ancien : le chapitre intestinal ESsCD publié en 2026 réutilise « EATL type II ». La classification OMS séparant EATL et MEITL est conservée ici. Une discordance de vocabulaire se résout par le domaine de compétence de chaque source, pas par sa date seule.</p>'),'CIM','OMS22','OMS-DC','ONKO','ESsCD26')

add('c86-enktl','ENKTL : tissu, EBV, extension et stratégie adaptée',
lab('Présentation','<p>L’ENKTL est une néoplasie extranodale associée à l’EBV, souvent de lignée NK, parfois T cytotoxique. Il prédomine en Asie et dans certaines populations d’Amérique centrale ou du Sud, mais existe en Europe. La revue Tse 2022 décrit environ 80 % de présentations nasales et 15–20 % non nasales dans son panorama clinique ; ces chiffres ne sont pas des incidences suisses. Une obstruction nasale unilatérale, des épistaxis ou une ulcération palatine nécrotique imposent une exploration ; une extension laryngée peut menacer immédiatement les voies aériennes.</p>')+
lab('Diagnostic','<p>Une biopsie représentative, comprenant du tissu viable en bordure des zones nécrotiques, est confrontée à la morphologie, aux marqueurs cytotoxiques et à EBER dans les cellules tumorales. La forme NK typique exprime CD3ε cytoplasmique, pas le CD3 membranaire, et garde le TCR en configuration germinale. Les formes de lignée T peuvent avoir un TCR réarrangé : ce profil NK n’est donc pas obligatoire dans tous les ENKTL. EBER positif avec CD56 ou des molécules cytotoxiques soutient ce diagnostic dans le contexte adapté ; cela ne suffit pas, seul, à exclure toutes les autres néoplasies EBV positives.</p>')+
lab('Bilan et marqueur','<p>TEP-TDM, examen médullaire et IRM des territoires ORL concernés définissent l’extension ; les signes neurologiques orientent l’exploration du SNC. L’ADN d’EBV plasmatique suit la charge tumorale et la réponse, en complément de l’imagerie. Il ne remplace ni la biopsie ni EBER. L’objectif est une réponse métabolique complète et un ADN d’EBV indétectable selon la méthode du laboratoire.</p>')+
lab('Traitement','<p>Chez le patient apte atteint d’une forme localisée, ESMO–EHA 2025 recommande une radiothérapie des sites impliqués d’au moins 50 Gy associée à une chimiothérapie sans anthracycline contenant de la L-asparaginase. Pour une maladie nasale de stade III–IV ou une forme extranasale, le schéma systémique et l’éventuelle greffe sont discutés en centre expert. Une radiothérapie seule reste envisageable dans certains stades I non volumineux ou si la fragilité interdit la chimiothérapie. Une atteinte ORL menaçante impose d’abord la sécurisation des fonctions vitales.</p>')+
lab('Limites','<p>La résistance à CHOP et la sensibilité à l’asparaginase orientent le choix collectif du traitement ; elles ne prédisent pas une réponse individuelle. Les comparaisons DDGP/SMILE sont discutées entre sources et ne démontrent pas une supériorité universelle. Oncaspar est autorisé en Suisse pour la LLA ; son emploi dans l’ENKTL est hors indication autorisée.</p>'),'TSE','ESMO25','OMS22','ONCASPAR')

add('c86-hstl','HSTL : le lymphome sans masse ganglionnaire évidente',
lab('Définition et mécanisme','<p>Le lymphome T hépatosplénique est une néoplasie T rare, souvent gamma-delta, caractérisée par une infiltration des sinusoïdes médullaires, spléniques et hépatiques. Des formes alpha-bêta et silencieuses pour le TCR existent. La distribution tissulaire explique l’hépatosplénomégalie et les cytopénies avec peu ou pas d’adénopathies ; une absence de ganglion palpable ne l’exclut donc pas.</p>')+
lab('Contexte','<p>La majorité des cas n’est pas réductible à une exposition médicamenteuse unique. Une immunosuppression prolongée, notamment au cours d’une maladie inflammatoire de l’intestin, est un contexte d’alerte. Chez l’homme jeune sous thiopurine, avec ou sans anti-TNF, fièvre, amaigrissement, splénomégalie et cytopénies justifient une évaluation rapide. Cette association ne permet pas d’attribuer toute fièvre au lymphome : infection, poussée inflammatoire et toxicité médullaire restent à discuter.</p>')+
lab('Ce que montrent les petits dénominateurs','<p>Carvão 2019 réunit 19 cas de Crohn sous thiopurine seule, dont le cas rapporté. Les signes cliniques sont disponibles pour 11 : tous ont une splénomégalie, sept une hépatomégalie, huit des symptômes généraux. L’hémogramme n’est décrit que chez sept : tous ont une thrombopénie, six une anémie et cinq une leucopénie. Ces proportions sélectionnées ne sont ni une sensibilité diagnostique ni une fréquence dans tous les HSTL.</p>')+
lab('Confirmation et traitement','<p>La biopsie médullaire et l’immunophénotype sont centraux. ESMO–EHA 2025 privilégie chez les patients aptes des schémas plus intensifs que CHOP, notamment ICE (ifosfamide, carboplatine, étoposide), puis une greffe de consolidation chez les répondeurs, de préférence allogénique. Le donneur est recherché précocement lorsque cette stratégie est envisageable. La TEP seule peut manquer une infiltration diffuse : la réponse doit être confrontée à la moelle et, si possible et indiqué, au foie.</p>')+
lab('Preuve et limite','<p>La comparaison citée dans la recommandation provient d’une synthèse de 166 patients, avec 50 sous CHOP/équivalent et 34 sous schémas non-CHOP dans la comparaison rapportée : réponses 52 % contre 82 %, survies médianes 18 contre 37 mois. L’absence de randomisation, la sélection des patients et les traitements différents empêchent d’en faire un effet causal individuel garanti.</p>'),'CARVAO','ESMO25','ONKO')

add('c86-eatl','EATL : entéropathie, signaux d’alarme et risque intestinal',
lab('Définition','<p>L’EATL est un lymphome T intestinal associé à la maladie cœliaque. La forme réfractaire de type II constitue un état à haut risque, sans que toute maladie cœliaque ou tout clone intraépithélial évolue vers un lymphome. Le MEITL est une entité distincte, généralement sans association à la maladie cœliaque. Le code, l’histologie actuelle et le contexte digestif doivent être confrontés.</p>')+
lab('Clinique','<p>Des douleurs abdominales persistantes, une perte de poids inexpliquée, une fièvre, une dénutrition ou une obstruction constituent des signaux d’alarme. L’EATL peut se révéler par une perforation, une hémorragie ou une occlusion ; une dégradation aiguë relève d’une évaluation hospitalière immédiate. La dénutrition et l’hypoalbuminémie augmentent aussi les difficultés et toxicités du traitement. Aucun de ces signes n’est spécifique du lymphome.</p>')+
lab('Démarche','<p>Le gastroentérologue vérifie le diagnostic initial de maladie cœliaque, l’observance du régime et les diagnostics alternatifs ; il organise biopsies, immunophénotypage des lymphocytes intraépithéliaux, analyse de clonalité, imagerie en coupe et entéroscopie selon la situation. La vidéocapsule peut guider l’exploration de la muqueuse, mais ne fournit pas d’histologie et n’est pas un examen à imposer sans appréciation des sténoses et du risque de rétention. Le parcours est coordonné avec l’hématopathologie et l’hématologie.</p>')+
lab('Traitement','<p>ESMO–EHA 2025 propose, chez certains patients aptes et éligibles à l’autogreffe, un cycle de CHOP ou CHOEP puis trois cycles d’IVE (ifosfamide, étoposide, épirubicine) alternés avec du méthotrexate à dose intermédiaire, puis une consolidation chez les répondeurs. D’autres schémas sont possibles selon l’aptitude ; BV-CHP ne doit pas être assimilé automatiquement à une autorisation européenne ou à une prise en charge suisse. La chirurgie répond aux complications ou à une discussion spécialisée de réduction du risque intestinal ; elle ne remplace pas la prise en charge systémique.</p>')+
lab('Pronostic','<p>Les 60 % de survie à cinq ans rapportés avec le programme intensif concernent une série sélectionnée de 26 patients et une comparaison historique. Ils ne s’appliquent pas à tous les malades dénutris ou fragiles. L’autogreffe utilise les propres cellules du patient : elle n’exige pas de donneur.</p>'),'ESsCD26','ESMO25','OMS22','ESGE22')

add('c86-sptcl','SPTCL : hypoderme, inflammation et traitement proportionné',
lab('Définition et diagnostic','<p>Le SPTCL correspond au lymphome T alpha-bêta sous-cutané de type panniculite. Les nodules ou plaques profonds traduisent l’atteinte de l’hypoderme. L’histologie recherche un infiltrat lymphocytaire atypique autour des adipocytes ; les cellules peuvent exprimer CD3, CD8, TIA1 et le marqueur de TCR alpha-bêta βF1. La biopsie doit donc contenir un hypoderme représentatif. L’architecture, la cytologie et le panel sont interprétés ensemble.</p>')+
lab('Différentiels','<p>Le lymphome T gamma-delta cutané primitif est une autre maladie, souvent plus agressive ; l’atteinte dermique/épidermique et l’ulcération peuvent orienter mais ne remplacent pas le phénotypage. La panniculite lupique est un autre diagnostic différentiel documenté par la recommandation S2k lupus 2021. Une biopsie et la confrontation clinico-pathologique sont nécessaires ; l’absence d’autoanticorps ne suffit pas à exclure un lupus cutané.</p>')+
lab('Urgence inflammatoire','<p>Fièvre persistante, cytopénies, splénomégalie, ferritine croissante, atteinte hépatique ou troubles de coagulation font rechercher un HLH. L’étude historique EORTC citée dans ESMO 2018 rapportait des survies globales à cinq ans de 91 % sans syndrome hémophagocytaire et 46 % avec : comparaison de groupes, pas démonstration que le syndrome « divise par deux » le pronostic de chaque personne.</p>')+
lab('Traitement','<p>Sans HLH, ESMO 2018 propose d’abord corticoïdes systémiques ou autres immunosuppresseurs tels que ciclosporine ou méthotrexate ; S2k 2021/2022 précise une prednisolone seule, avec association possible selon le besoin. Une radiothérapie peut être discutée pour une lésion solitaire. Une progression malgré l’immunosuppression ou un HLH exige une réévaluation spécialisée urgente ; la décision d’immunomodulation, de chimiothérapie et de traitement du déclencheur dépend de la gravité, et pas seulement du résultat HAVCR2.</p>')+
lab('Limite pharmacologique','<p>Ces recommandations de stratégie ne constituent pas une posologie suisse universelle du SPTCL. Le protocole, les infections, la fonction rénale/hépatique et les interactions doivent être examinés avant une prescription immunosuppressive.</p>'),'CUT18','S2K','LUPUS','MOONLA','HLH23')

add('c86-bpdcn','BPDCN : une néoplasie dendritique dans une ancienne rubrique NK',
lab('Lignée et clinique','<p>Le BPDCN dérive de cellules dendritiques plasmacytoïdes et appartient aux néoplasies dendritiques/histiocytaires dans l’OMS 2022. Il touche surtout l’adulte âgé avec prédominance masculine, mais des formes pédiatriques existent. Plaques ou nodules violacés, lésions d’allure ecchymotique, cytopénies, atteinte médullaire et ganglionnaire peuvent s’associer. Une présentation sans lésion cutanée est possible.</p>')+
lab('Critères immunophénotypiques OMS 2022','<p>Deux voies sont décrites : <b>CD123 et au moins un autre marqueur pDC</b> parmi TCF4, TCL1, CD303 et CD304, avec CD4 et/ou CD56 ; <b>ou au moins trois marqueurs pDC</b> avec absence des marqueurs négatifs attendus (CD3, CD14, CD19, CD34, lysozyme et myéloperoxydase). Il ne s’agit donc pas d’exiger simultanément CD4, CD56 et TCL1 dans tout cas. La morphologie et les diagnostics différentiels, notamment leucémie myéloïde/sarcome myéloïde et lymphomes T/NK, restent essentiels.</p>')+
lab('Bilan du SNC','<p>Le consensus international 2023 recommande fortement une ponction lombaire diagnostique au diagnostic et une analyse sensible du liquide céphalorachidien, avec plan de prophylaxie intrathécale pendant l’induction en centre expert. Sa réalisation dépend de la stabilité clinique, des contre-indications et de l’hémostase. L’absence de signe neurologique n’exclut pas une atteinte occulte. Le tagraxofusp ne dispense pas de ce bilan : son passage de la barrière hémato-encéphalique est inconnu dans la FI suisse.</p>')+
lab('Traitement et limites','<p>Elzonris est autorisé en Suisse en première ligne chez l’adulte. Chez les patients aptes, une allogreffe est envisagée idéalement en première rémission complète ; l’âge, les comorbidités, la réponse et le donneur déterminent l’éligibilité. L’autogreffe est une possibilité sélectionnée lorsque le risque d’allogreffe est trop élevé ou qu’un donneur adapté manque, sur preuves limitées ; elle n’est pas un substitut automatique. Le consensus 2023 souligne l’absence de comparaison randomisée directe entre stratégies ciblées et chimiothérapie.</p>')+
lab('Enfant','<p>La prise en charge pédiatrique est distincte ; la FI suisse d’Elzonris ne fournit pas d’autorisation ni de recommandation posologique pédiatrique. L’autorisation américaine mentionnée dans certaines publications ne doit pas être transposée à la Suisse.</p>'),'OMS-DC','BPDCN23','ELZONRIS')

add('c86-ntfh','nTFHL-AI : architecture ganglionnaire et désordre immunitaire',
lab('Identifier le type','<p>Le lymphome TFH nodal de type angio-immunoblastique est l’ancien AITL. Le phénotype TFH associe CD4 à au moins deux marqueurs parmi PD1, ICOS, CXCL13, CD10 et BCL6 ; leur intensité, leur distribution et leur spécificité comptent. Deux marqueurs ne suffisent pas à définir à eux seuls le type angio-immunoblastique. L’architecture ganglionnaire, l’infiltrat polymorphe et les veinules à endothélium haut arborisées contribuent à la classification.</p>')+
lab('Pourquoi plusieurs lignées peuvent être perturbées','<p>Les mutations TET2/DNMT3A peuvent apparaître dans une cellule souche hématopoïétique, avant les anomalies RHOA/IDH2 observées dans la population TFH tumorale. Une anomalie épigénétique détectée dans le sang n’est donc pas nécessairement une preuve de lymphome TFH. L’hypergammaglobulinémie polyclonale, une hémolyse auto-immune ou des cellules B EBV positives peuvent accompagner la dérégulation du microenvironnement ; EBER doit être localisé à la bonne population.</p>')+
lab('Prise en charge','<p>CHOP ou CHOEP est proposé par ESMO–EHA 2025. Une forme limitée, non volumineuse et de profil favorable peut recevoir un programme abrégé de trois à quatre cycles ; une radiothérapie de consolidation et une autogreffe sont discutées selon la réponse et le risque. Le fait d’exprimer CD30 ne démontre pas à lui seul un bénéfice de BV-CHP dans cette entité : le bénéfice global d’ECHELON-2 était surtout porté par les lymphomes anaplasiques systémiques.</p>')+
lab('Rechute','<p>Une nouvelle biopsie peut révéler un autre processus, y compris une prolifération B ou myéloïde. Un essai clinique et l’allogreffe chez un patient apte et chimiosensible sont discutés. L’azacitidine orale a une activité étudiée, mais l’essai de phase III cité par ESMO 2025 n’a pas atteint son critère principal de supériorité en survie sans progression. Son emploi n’est pas une conséquence automatique d’une mutation TET2.</p>'),'OMS22','ESMO25','ONKO')

add('c86-cd30','C86.6 : LyP et pcALCL, même marqueur mais évolution différente',
lab('Clinique discriminante','<p>La papulose lymphomatoïde donne des poussées de papules ou nodules parfois nécrotiques dont chaque lésion régresse spontanément en semaines à mois. Le pcALCL se présente plutôt comme une tumeur ou un nodule solitaire, groupé ou plus rarement multifocal. Une biopsie CD30 positive peut se ressembler dans ces deux situations : la chronologie documentée, les photographies cliniques et l’examen de toute la peau apportent une information indispensable.</p>')+
lab('Critères et bilan','<p>Dans le contexte adapté, le pcALCL montre CD30 sur au moins 75 % des cellules tumorales. Il faut exclure une LyP, un mycosis fongoïde transformé et un lymphome systémique avec atteinte secondaire de la peau. ALK positif impose une recherche soigneuse d’atteinte systémique ; de rares cas primitifs cutanés ALK positifs ont cependant été décrits, empêchant une règle absolue fondée sur ce seul marqueur.</p>')+
lab('Pronostic et dénominateurs','<p>Dans les registres cutanés néerlandais et autrichien 2002–2017, LyP et pcALCL représentent respectivement 12 % et 8 % de tous les lymphomes cutanés, avec survies spécifiques à cinq ans de 99 % et 95 %. L’ensemble des proliférations CD30 positives représente environ 25 % des <em>lymphomes T cutanés</em> : le dénominateur diffère. Les rechutes cutanées sont fréquentes dans le pcALCL, alors que la dissémination extracutanée concerne une minorité.</p>')+
lab('Conduite','<p>La LyP peut être surveillée ou traitée pour contrôler les poussées ; aucune prévention certaine d’un second lymphome par le traitement n’est démontrée. Pour une lésion de pcALCL solitaire ou groupée, excision ou radiothérapie sont privilégiées. Une maladie multifocale, réfractaire ou extracutanée fait discuter un traitement systémique adapté. Le suivi de la LyP reste prolongé, même lorsque les lésions disparaissent.</p>'),'WHO-CUT','KEMPF','CUT18','ADCETRIS')

add('c86-ebv','EBER tissulaire et ADN d’EBV plasmatique : deux questions',
lab('Tissu','<p>EBER est recherché par hybridation in situ dans le prélèvement. Il faut déterminer quelles cellules portent le virus : des cellules B réactives ou associées à un lymphome TFH peuvent être EBV positives sans définir un ENKTL. La sérologie EBV témoigne d’une exposition immunologique, pas de la nature de la tumeur.</p>')+
lab('Plasma','<p>Des fragments d’ADN viral sont libérés dans la circulation lors de la mort des cellules tumorales. Le dosage plasmatique est ainsi un marqueur de charge tumorale et de réponse. Tse 2022 privilégie le plasma, car les lymphocytes B mémoires EBV infectés présents dans le sang total peuvent ajouter un signal qui n’est pas celui du lymphome. ESMO–EHA 2025 recommande une PCR quantitative au diagnostic et pendant le traitement.</p>')+
lab('Interprétation','<p>Une valeur détectable n’est pas un diagnostic autonome, et une valeur indétectable dépend de la limite analytique du laboratoire. Le suivi emploie autant que possible la même matrice et la même méthode, en conservant unités et limite de détection dans le compte rendu. La cinétique est confrontée à la clinique et à la TEP ; un nombre de copies isolé ne déclenche pas automatiquement un changement de traitement.</p>'),'TSE','ESMO25')

add('c86-pgp','Deux propriétés biologiques qui orientent le traitement de l’ENKTL',
lab('Résistance','<p>Le phénotype de multirésistance, notamment l’expression de la glycoprotéine P, contribue aux mauvais résultats des schémas à anthracycline de type CHOP. Les recommandations choisissent donc des programmes sans anthracycline pour l’ENKTL. Cette décision repose sur les données cliniques et la biologie, pas sur un test isolé de P-gp réalisé chez chaque patient.</p>')+
lab('Dépendance métabolique','<p>L’activité souvent faible de l’asparagine synthétase limite la capacité des cellules à compenser une déplétion en asparagine extracellulaire. L’asparaginase hydrolyse cette asparagine et prive les cellules sensibles d’un substrat pour la synthèse protéique. La pégylation prolonge l’exposition à l’enzyme ; elle ne transforme pas les unités d’une préparation en équivalents interchangeables de celles d’une autre.</p>')+
lab('Conséquence clinique','<p>Une chimiothérapie contenant de la L-asparaginase est associée à la radiothérapie dans les formes localisées aptes et constitue la base de nombreux programmes avancés. Les allergies ou anticorps inactivants peuvent réduire l’activité enzymatique malgré une dose administrée ; la FI Oncaspar envisage le suivi d’activité et une autre préparation. La toxicité pancréatique, hépatique et de coagulation impose une surveillance parallèle.</p>'),'TSE','ESMO25','ONCASPAR')

add('c86-havcr2','HAVCR2/TIM-3 : prédisposition, mécanisme et limites statistiques',
lab('Normal et anomalie','<p>TIM-3 est un régulateur de réponses immunitaires exprimé sur plusieurs populations T et innées. Les variants germinaux HAVCR2 décrits par Gayden 2018 entraînent un mauvais repliement et une perte d’expression membranaire, avec activation immunitaire persistante et augmentation de cytokines inflammatoires. Le résumé de cette étude rapporte environ 60 % de cas porteurs dans sa série ; ce n’est pas une prévalence suisse universelle. Moonla 2023 évoque une plage de 25–60 % selon les études.</p>')+
lab('Population et association','<p>Moonla inclut une cohorte de 34 patients dans neuf centres thaïlandais, dont 28 SPTCL et six HLH sans panniculite ; l’analyse individuelle agrégée porte sur 127 patients issus de quatre cohortes. Les odds ratios ajustés d’association au HLH/état apparenté sont 2,93 pour le sexe masculin, 4,77 pour l’hétérozygotie et 8,48 pour l’homozygotie ou hétérozygotie composite, avec des intervalles de confiance parfois larges. Ce sont des associations observées, ni des risques absolus ni une prédiction certaine pour un porteur.</p>')+
lab('Décision','<p>L’âge jeune et le génotype orientent la vigilance et une discussion génétique spécialisée. Le HLH doit être reconnu et traité sur son tableau clinique, sans attendre HAVCR2. Les observations d’amélioration sous immunomodulation ne constituent pas un essai comparatif prouvant un même schéma pour tous les génotypes. Un variant trouvé dans un contexte tumoral ne doit pas être qualifié de germinal sans démarche génétique appropriée.</p>'),'GAYDEN','MOONLA','HLH23')

add('c86-slh','HLH : reconnaître l’hyperinflammation et agir en parallèle',
lab('Reconnaître','<p>Le syndrome d’activation lymphohistiocytaire, ou HLH, associe une activation immunitaire excessive et une atteinte d’organes. Fièvre persistante, splénomégalie, cytopénies, ferritine croissante, anomalies hépatiques et coagulation perturbée doivent alerter. Un sepsis, une infection, une maladie inflammatoire et un lymphome peuvent se recouvrir ou coexister. Une ferritine élevée seule n’est pas diagnostique.</p>')+
lab('HLH-2004 : cinq critères sur huit, ou diagnostic moléculaire compatible', table(['Critère','Seuil ou observation dans la table de La Rosée 2019'],[
['1. Fièvre','Critère clinique ; le seuil thermique n’est pas chiffré dans cette table.'],['2. Splénomégalie','Clinique ou documentée par imagerie.'],['3. Cytopénies','Au moins deux lignées : Hb <90 g/L ; plaquettes <100 × 10⁹/L ; neutrophiles <1,0 × 10⁹/L. Le seuil d’Hb du nourrisson <4 semaines est distinct.'],['4. Triglycérides et/ou fibrinogène','Triglycérides à jeun ≥3,0 mmol/L et/ou fibrinogène ≤1,5 g/L.'],['5. Hémophagocytose','Moelle, rate ou ganglions ; elle n’est ni constamment visible ni spécifique à elle seule.'],['6. Activité NK','Faible ou absente selon la référence du laboratoire.'],['7. Ferritine','≥500 µg/L, seuil peu spécifique chez l’adulte.'],['8. sCD25','Récepteur soluble de l’IL-2 ≥2 400 U/mL selon la méthode concernée.']]))+
lab('Limites','<p>Ces critères ont été développés dans des essais pédiatriques ; l’adulte exige une interprétation clinique. La formulation historique de la table concernant l’hémophagocytose ne doit pas être lue comme une exclusion de toute malignité : le HLH associé au lymphome est précisément un contexte majeur des recommandations adultes. L’absence d’hémophagocytose ou de cinq critères au début ne permet pas de rassurer un patient qui se dégrade. Le HScore peut compléter l’évaluation dans son contexte, sans remplacer le jugement clinique.</p>')+
lab('Conduite urgente','<p>EULAR/ACR recommande d’évaluer simultanément les fonctions vitales, les déclencheurs infectieux ou malins, la nécessité de soins intensifs et l’immunomodulation. Chez un patient à haut risque ou en aggravation, celle-ci peut être envisagée pendant le bilan, en concertation spécialisée. Corticoïdes, anakinra ou immunoglobulines sont des options contextuelles citées ; les protocoles contenant de l’étoposide et le traitement du lymphome relèvent du contexte étiologique. Aucun schéma pédiatrique complet n’est transposé automatiquement à l’adulte dans ce cours.</p>'),'HLH19','HLH23','CUT18')

add('c86-rcd','Maladie cœliaque réfractaire de type II : critères et surveillance',
lab('Définition actuelle lue','<p>ESsCD 2025, partie 2 publiée en 2026, définit la forme réfractaire par des symptômes persistants ou récidivants et une atrophie villositaire après <b>au moins 12 mois</b> de régime strict sans gluten, après exclusion des autres causes. Le diagnostic initial, l’exposition persistante au gluten, une réponse lente et d’autres maladies digestives doivent être réexaminés.</p>')+
lab('Type II','<p>Les lymphocytes intraépithéliaux aberrants perdent CD3 de surface et CD8 tout en gardant CD3 cytoplasmique. La cytométrie retrouve typiquement <b>au moins 20 %</b> de cellules aberrantes ; l’étude du réarrangement TCR apporte une preuve de clonalité. Ce pourcentage est lié à une technique et ne doit pas être transposé tel quel à toute immunohistochimie. Un clone aberrant sans symptômes, anomalies biologiques ou lésions significatives requiert une interprétation prudente et peut justifier une surveillance plutôt qu’un traitement agressif immédiat.</p>')+
lab('Bilan et risque','<p>Biopsies duodénales bien conditionnées, immunophénotypage, clonalité, imagerie, entéroscopie et parfois vidéocapsule participent au bilan spécialisé. L’EATL doit être recherché avant de conclure à une forme réfractaire. La jéjunite ulcéreuse est une complication associée, pas une définition autonome de RCD-II. Le risque de transformation est élevé dans cette population sélectionnée : la source décrit un EATL chez jusqu’à la moitié des patients, sans appliquer ce chiffre à toute maladie cœliaque.</p>')+
lab('Suivi','<p>La dénutrition, les douleurs, la perte de poids, la fièvre ou l’obstruction déclenchent une réévaluation. ESMO–EHA 2025 propose de considérer des contrôles tous les 6–12 mois en RCD-II, avec imagerie du grêle notamment devant de nouveaux signes préoccupants ; le rythme et la modalité sont individualisés par l’équipe experte. Une suspicion de complication aiguë ne doit pas attendre ce rendez-vous programmé.</p>'),'ESsCD26','ESMO25')

add('c86-tfh','Du lymphocyte TFH normal à la prolifération tumorale',
lab('Fonction et phénotype','<p>Les lymphocytes T folliculaires auxiliaires participent à la réponse des cellules B dans les structures lymphoïdes. PD1, ICOS, CXCL13, CD10 et BCL6 servent de marqueurs de cette différenciation ; leur expression peut aussi exister dans des cellules normales ou réactives. Pour un lymphome nodal, l’OMS demande CD4 et au moins deux marqueurs TFH, en confrontation avec l’architecture et la clinique.</p>')+
lab('Étapes moléculaires','<p>Le modèle de l’OMS place TET2 et DNMT3A précocement dans l’hématopoïèse clonale, puis des anomalies RHOA et IDH2 dans la population TFH néoplasique. C’est une explication biologique de données collectives, pas une chronologie séquencée chez chaque patient. Une mutation TET2 dans le sang peut concerner d’autres lignées et ne suffit pas à diagnostiquer nTFHL-AI.</p>')+
lab('Clinique et limite','<p>Le microenvironnement perturbé peut s’accompagner d’hypergammaglobulinémie polyclonale, d’hémolyse auto-immune et de proliférations B EBV positives. La preuve d’une hémolyse demande une baisse d’Hb et un faisceau biologique compatible, pas un Coombs positif isolé. Le choix d’un traitement épigénétique n’est pas dicté par une mutation unique.</p>'),'OMS22','ESMO25','HUG')

add('c86-tcr','Clonalité du récepteur T : utile, jamais suffisante seule',
lab('Normalité','<p>Les cellules T développent des réarrangements des gènes du récepteur T ; une réponse immunitaire normale peut sélectionner et amplifier certains clones. Les cellules NK n’utilisent pas ce récepteur réarrangé. Le phénotype membranaire et les études de gènes répondent à des questions complémentaires.</p>')+
lab('Maladie','<p>Un clone dominant peut étayer une prolifération T néoplasique, mais des clones non malins donnent des résultats positifs ; inversement, une tumeur T peut donner un profil apparemment polyclonal selon la qualité, l’échantillonnage et la méthode. ESMO–EHA 2025 recommande une interprétation intégrant morphologie, phénotype aberrant et données moléculaires.</p>')+
lab('Exemples','<p>Un ENKTL de lignée NK garde habituellement les gènes TCR en configuration germinale ; une forme de lignée T peut être réarrangée. Le HSTL est le plus souvent gamma-delta, parfois alpha-bêta ou silencieux. Dans RCD-II, le réarrangement TCR contribue à caractériser la population intraépithéliale aberrante mais ne remplace pas les critères digestifs.</p>'),'ESMO25','TSE','ESsCD26','ONKO')

add('c86-thiopurine','Thiopurines et HSTL : lire correctement le risque absolu',
lab('Population','<p>La revue Carvão 2019 cite, chez les <b>hommes de moins de 35 ans</b>, des risques estimés de 1/7 404 sous thiopurine seule et 1/3 534 sous association thiopurine–anti-TNF. Ils ne doivent pas être attribués à tous les patients atteints de Crohn, ni présentés comme un risque annuel : l’horizon temporel n’est pas défini par ce passage.</p>')+
lab('Calcul illustratif','<p>1 ÷ 7 404 × 100 ≈0,0135 % ; 1 ÷ 3 534 × 100 ≈0,0283 %. Leur rapport arithmétique est environ 2,10 et leur différence environ 0,0148 point de pourcentage. Cette comparaison de deux estimations publiées ne prouve pas à elle seule un effet causal ajusté du médicament et ne prédit pas le risque personnel.</p>')+
lab('Décision clinique','<p>La revue rapporte qu’une grande partie des cas sous association survient après deux ans et cite des recommandations historiques de limitation chez le jeune homme. Elle ne formule pas de règle formelle de durée de la thiopurine seule. Ce cours ne transforme pas cette revue de cas en consigne d’arrêt automatique : l’équipe de gastroentérologie réévalue bénéfice, contrôle de la maladie, alternatives et risques. Une fièvre avec splénomégalie/cytopénies nécessite une évaluation sans attendre une durée d’exposition particulière.</p>'),'CARVAO','ONKO')
